 *
 * `createOrdersClient(service, options)` must return an object with `getOrder(id)` and `createOrder(input)`.
 * `options.sleep(ms)` is how you wait — never use timers directly. See specification.md for the contract, and
 * conformance/cases.mjs for exactly what is checked.
 */

function isRetryableStatus(status) {
	return status === 429 || (status >= 500 && status <= 599);
}

export function createOrdersClient(service, options) {
	const sleep = options?.sleep;
	const maxAttempts = options?.maxAttempts ?? 4;
	const baseDelayMs = options?.baseDelayMs ?? 100;

	async function call(method, path, requestOptions) {
		let attempt = 0;
		for (;;) {
			attempt += 1;
			const { status, body } = await service.request(method, path, requestOptions);
			if (status >= 200 && status < 300) return body;

			const code = body?.error?.code ?? "unknown_error";
			if (code === "validation_failed") {
				const err = new Error(body.error.message ?? "validation failed");
				err.name = "ValidationError";
				err.fields = body.error.fields ?? [];
				throw err;
			}

			const retryable = isRetryableStatus(status);
			if (!retryable || attempt >= maxAttempts) {
				const err = new Error(body?.error?.message ?? `request failed with status ${status}`);
				err.name = "ServiceError";
				err.status = status;
				err.code = code;
				err.attempts = attempt;
				throw err;
			}

			const waitMs = status === 429 ? body.retryAfterMs : baseDelayMs * 2 ** (attempt - 1);
			await sleep(waitMs);
		}
	}

	async function getOrder(id) {
		try {
			return await call("GET", `/orders/${id}`);
		} catch (err) {
			if (err.name === "ServiceError" && err.code === "not_found") return null;
			throw err;
		}
	}

	async function createOrder(input) {
		return call("POST", "/orders", { body: input });
	}

	return { getOrder, createOrder };
}
